from collections import defaultdict
class Solution:
    def maxStudentsOnBench(self, students: List[List[int]]) -> int:
        d = defaultdict(set)
        for sid, b in students:
            d[b].add(sid)
        return max((len(v) for v in d.values()), default=0)

