class Solution {
public:
    int maxStudentsOnBench(vector<vector<int>>& students) {
        unordered_map<int, unordered_set<int>> d;
        for (auto& s : students) d[s[1]].insert(s[0]);
        int ans = 0;
        for (auto& [b, set_] : d) ans = max(ans, (int)set_.size());
        return ans;
    }
};

