class Solution {
    public int maxStudentsOnBench(int[][] students) {
        Map<Integer, Set<Integer>> d = new HashMap<>();
        for (int[] s : students) d.computeIfAbsent(s[1], x -> new HashSet<>()).add(s[0]);
        int ans = 0;
        for (Set<Integer> v : d.values()) ans = Math.max(ans, v.size());
        return ans;
    }
}

