var maxStudentsOnBench = function(students) {
    const d = new Map();
    for (const [sid, b] of students) {
        if (!d.has(b)) d.set(b, new Set());
        d.get(b).add(sid);
    }
    let ans = 0;
    for (const v of d.values()) ans = Math.max(ans, v.size);
    return ans;
};
